css:
.card {
  color: var(--uxdsl__palette__primary-main);
}
.card__title {
  padding: var(--uxdsl__density__2);
}
.card:hover {
  color: var(--uxdsl__palette__primary-dark);
}
.icon .card {
  border: var(--uxdsl__border__1);
}
@media (min-width: 600px) {
  .card {
    padding: var(--uxdsl__space__4);
  }
}
